from fractions import Fraction


def informed_loss(bid, ask, outcomes):
    """Average loss a game to a counterparty who sees
    the outcome (outcomes equally likely)."""
    total = Fraction(0)
    for x in outcomes:
        if x > ask:
            total += x - ask
        elif x < bid:
            total += bid - x
    return total / len(outcomes)


def mixed_pnl(bid, ask, alpha, outcomes, fair):
    """Average P&L a game when a share alpha is informed
    and the rest buy or sell one at random."""
    noise = Fraction(1, 2) * (ask - fair) + Fraction(1, 2) * (fair - bid)
    return (1 - alpha) * noise - alpha * informed_loss(bid, ask, outcomes)
